1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	
6	const BASE_PREMIUMS: Record<string, number> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	  rune: 25,
12	  moonstone: 25,
13	};
14	
15	// Components (as opposed to main items) are the only things the block rule
16	// applies to, so the distinction has to be data, not a price coincidence.
17	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
18	
19	const PERCENT_WHOLE = 100;
20	
21	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
22	// floating-point error that shifts the spec's round-up in MHPCO's favour.
23	const percentOf = (percent: number, amount: number): number =>
24	  (amount * percent) / PERCENT_WHOLE;
25	
26	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
27	// round up, payouts (MHPCO pays) round down.
28	const roundPremiumInMHPCOsFavour = Math.ceil;
29	
30	export type ScenarioResult = { premium: number };
31	
32	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
33	// the surcharge and claim tests still to come). They are typed as optional so
34	// the scenarios the tests actually send typecheck, without pricing them.
35	type Item = {
36	  type: string;
37	  material?: string;
38	  enchantment?: number;
39	  cursed?: boolean;
40	};
41	
42	type Step = { op: string; items: Item[] };
43	
44	// `customer` and `op` are likewise unread so far: the loyalty-discount and
45	// follow-up-contract tests will reach for them.
46	type Scenario = {
47	  customer: { yearsWithMHPCO: number };
48	  steps: Step[];
49	};
50	
51	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
52	
53	const sumBasePremiums = (items: Item[]): number =>
54	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
55	
56	const groupByType = (items: Item[]): Item[][] => {
57	  const groups = new Map<string, Item[]>();
58	  for (const item of items) {
59	    const group = groups.get(item.type) ?? [];
60	    group.push(item);
61	    groups.set(item.type, group);
62	  }
63	  return [...groups.values()];
64	};
65	
66	// A block is a discount on the components' combined base premium, not a flat
67	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
68	// 20 % stays visible as the rule it is.
69	const blockBasePremium = (items: Item[]): number => {
70	  const undiscounted = sumBasePremiums(items);
71	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
72	};
73	
74	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
75	// pile is never cheaper than the block it contains. Components only — three
76	// swords are three separate insurances, not a discounted building block.
77	const formsABlock = (alikeItems: Item[]): boolean =>
78	  alikeItems.length === BLOCK_SIZE && COMPONENT_TYPES.has(alikeItems[0].type);
79	
80	const basePremiumForGroup = (alikeItems: Item[]): number =>
81	  formsABlock(alikeItems) ? blockBasePremium(alikeItems) : sumBasePremiums(alikeItems);
82	
83	// Priced per group of alike items rather than over the whole list, so 3 runes
84	// and 3 moonstones each form their own block.
85	const policyBasePremiumFor = (items: Item[]): number =>
86	  groupByType(items)
87	    .map(basePremiumForGroup)
88	    .reduce((total, groupPremium) => total + groupPremium, 0);
89	
90	const quoteFor = (items: Item[]): ScenarioResult => {
91	  const policyBasePremium = policyBasePremiumFor(items);
92	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
93	  const premium = roundPremiumInMHPCOsFavour(
94	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
95	  );
96	  return { premium };
97	};
98	
99	// Every scenario so far holds exactly one quote step, so only the first is
100	// priced. The follow-up-contract discount test will drive priced-per-step.
101	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
102	  const [firstStep] = scenario.steps;
103	  return { results: [quoteFor(firstStep.items)] };
104	};
